// ------------------------------------------------------------------
// HELPERS
// ------------------------------------------------------------------

const genId = () => Math.random().toString(36).substr(2, 9);

const initialScore: ScoreState = {
  p1Points: '0',
  p2Points: '0',
  p1Games: 0,
  p2Games: 0,
  p1Sets: 0,
  p2Sets: 0,
  p1SetScores: [0],
