export const subscribeToTournaments = (cb: (data: Tournament[]) => void) => {
    if (!db) return () => {};
    const q = query(collection(db, "tournaments"), orderBy("createdAt", "desc"));
    return onSnapshot(q, (snapshot) => {
        const tours = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Tournament));
        cb(tours);
    });
};

export const subscribeToTournament = (id: string, cb: (data: Tournament | null) => void) => {
    if (!db) return () => {};
    return onSnapshot(doc(db, "tournaments", id), (doc) => {
        if (doc.exists()) {
            cb({ id: doc.id, ...doc.data() } as Tournament);
        } else {
            cb(null);
        }
    });
};

export const createTournament = async (t: any) => {
    if (!db) throw new Error("Database not initialized");
    const newT = { 
        ...t, 
        teams: [], 
        matches: [], 
        status: 'ACTIVE', 
        createdAt: new Date().toISOString() 
    };
    const docRef = await addDoc(collection(db, "tournaments"), newT);
    return docRef.id;
};

export const registerTeam = async (tId: string, team: any) => {
    if (!db) return;
    const tRef = doc(db, "tournaments", tId);

    // Using simple get/update pattern.
    const snap = await getDoc(tRef);
    if (!snap.exists()) return;

    const tData = snap.data() as Tournament;
    const newTeam = { 
        ...team, 
        id: genId(), 
        status: RegistrationStatus.PENDING, 
        registeredAt: new Date().toISOString() 
    };

    await updateDoc(tRef, {
        teams: [...tData.teams, newTeam]
    });
};

