    const tData = snap.data() as Tournament;
    const updatedTeams = tData.teams.map(tm => 
        tm.id === teamId ? { ...tm, status: status as RegistrationStatus } : tm
    );

    await updateDoc(tRef, { teams: updatedTeams });
};

