export const subscribeToTournaments = (cb: (data: Tournament[]) => void) => {
    const notify = () => cb(getLocalTournaments());
    window.addEventListener(EVENT_KEY, notify);
    notify(); // Initial load
    return () => window.removeEventListener(EVENT_KEY, notify);
};

export const subscribeToTournament = (id: string, cb: (data: Tournament | null) => void) => {
    const notify = () => {
        const all = getLocalTournaments();
        const t = all.find(x => x.id === id) || null;
        cb(t);
    };
    window.addEventListener(EVENT_KEY, notify);
    notify();
    return () => window.removeEventListener(EVENT_KEY, notify);
};

