export const subscribeToTournaments = (cb: (data: Tournament[]) => void) => {
    if (isFirebaseConfigured && db) {
        const q = query(collection(db, "tournaments"), orderBy("createdAt", "desc"));
        return onSnapshot(q, (snapshot) => {
            const tours = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Tournament));
            cb(tours);
        });
    } else {
        const notify = () => cb(getLocal());
        window.addEventListener(EVENT_KEY, notify);
        notify();
        return () => window.removeEventListener(EVENT_KEY, notify);
    }
};

export const subscribeToTournament = (id: string, cb: (data: Tournament | null) => void) => {
    if (isFirebaseConfigured && db) {
        return onSnapshot(doc(db, "tournaments", id), (doc) => {
            if (doc.exists()) cb({ id: doc.id, ...doc.data() } as Tournament);
            else cb(null);
        });
    } else {
        const notify = () => {
            const t = getLocal().find(x => x.id === id) || null;
            cb(t);
        };
        window.addEventListener(EVENT_KEY, notify);
        notify();
        return () => window.removeEventListener(EVENT_KEY, notify);
    }
};

