const STORAGE_KEY = 'matchup_tournaments_local';
const EVENT_KEY = 'matchup_storage_update';

const getLocal = (): Tournament[] => {
    try {
        const d = localStorage.getItem(STORAGE_KEY);
        return d ? JSON.parse(d) : [];
    } catch { return []; }
};

const saveLocal = (d: Tournament[]) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(d));
    window.dispatchEvent(new Event(EVENT_KEY));
};

export const subscribeToTournaments = (cb: (data: Tournament[]) => void) => {
    const notify = () => cb(getLocal());
    window.addEventListener(EVENT_KEY, notify);
    notify();
    return () => window.removeEventListener(EVENT_KEY, notify);
};

export const subscribeToTournament = (id: string, cb: (data: Tournament | null) => void) => {
    const notify = () => {
        const t = getLocal().find(x => x.id === id) || null;
        cb(t);
    };
    window.addEventListener(EVENT_KEY, notify);
    notify();
    return () => window.removeEventListener(EVENT_KEY, notify);
};

