    ScoreState, 
    RegistrationStatus, 
    TournamentFormat, 
    RoundRobinType, 
    MatchDependency 
} from '../types';

// ==================================================================
// ⚙️ CONFIGURATION: PASTE YOUR FIREBASE KEYS HERE
// ==================================================================

const firebaseConfig = {
  // 1. Go to console.firebase.google.com
  // 2. Create a project -> Build -> Firestore Database (Start in Test Mode)
  // 3. Project Settings -> Add Web App -> Copy these values:
  apiKey: "YOUR_API_KEY_HERE",
  authDomain: "YOUR_PROJECT_ID.firebaseapp.com",
