export const SetupScreen: React.FC = () => {
    const [configInput, setConfigInput] = useState('');
    const [error, setError] = useState('');

    const handleSave = () => {
        try {
            // Allow user to paste the whole 'const firebaseConfig = { ... }' or just the object
            let cleanJson = configInput;

            // cleanup if they pasted the variable declaration
            if (cleanJson.includes('=')) {
                cleanJson = cleanJson.substring(cleanJson.indexOf('=') + 1);
            }
            if (cleanJson.trim().endsWith(';')) {
                cleanJson = cleanJson.trim().slice(0, -1);
            }

            // Using Function to loosen JSON parsing (allows keys without quotes which standard JSON.parse fails on)
            // Warning: eval-like, but client-side only and for configuration.
            // eslint-disable-next-line
            const config = new Function('return ' + cleanJson)();

            if (!config.apiKey || !config.projectId) {
                throw new Error("Invalid Configuration Object");
            }

            saveBackendConfig(config);
        } catch (e) {
            setError('Invalid format. Please paste the "firebaseConfig" object exactly as shown in Firebase console.');
