            await updateDoc(tRef, { teams: updatedTeams });
        }
    } else {
        const t = mockTournaments.find(x => x.id === tId);
        if (t) {
            t.teams = t.teams.map(tm => tm.id === teamId ? { ...tm, groupId } : tm);
            notifyMock();
        }
    }
};

