                            <div className="flex items-center gap-2 text-gray-400"><Phone size={14}/> {team.player2.phone}</div>
                            <div className="flex items-center gap-2 text-gray-400"><Mail size={14}/> {team.player2.email}</div>
                        </div>
                    </div>
                </div>
            )}
