                                    <button onClick={(e) => { e.stopPropagation(); updateTeamStatus(tournament.id, t.id, 'REJECTED'); }} className="p-1 bg-red-500/20 text-red-500 rounded hover:bg-red-500/30 transition-colors"><X size={16}/></button>
