                                     <img src={src} className="max-w-full max-h-full object-contain" />
                                     <button onClick={() => removeSponsor(i)} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-0.5 hover:bg-red-600"><X size={12}/></button>
