    if (db) {
        await deleteDoc(doc(db, "tournaments", tId));
    } else {
        mockTournaments = mockTournaments.filter(t => t.id !== tId);
        notifyMock();
    }
};

export const updateTournament = async (tId: string, data: Partial<Tournament>) => {
