// ------------------------------------------------------------------
// UTILS
// ------------------------------------------------------------------
// Robust Deep Clone to handle circular refs and strip undefined
const cleanData = (data: any) => {
    const seen = new WeakMap();

    const clone = (obj: any): any => {
        // Handle primitives and null
        if (obj === null || typeof obj !== 'object') {
            return obj === undefined ? null : obj;
        }

        // Handle specific types
        if (obj instanceof Date) return obj.toISOString();
        if (obj instanceof RegExp) return obj.toString();

        // Safety: Block DOM nodes, React Elements, and potential internal Firebase objects that cause cycles
        // Checks for 'nodeType' (DOM), '$$typeof' (React), or complex prototype chains that might indicate internal objects
        if (obj.nodeType || obj.$$typeof || (obj.constructor && obj.constructor.name && (obj.constructor.name.startsWith('_') || obj.constructor.name === 'SyntheticBaseEvent'))) {
            return null; 
        }

        // Detect Cycles
        if (seen.has(obj)) {
            return null; // Break cycle by returning null
        }
        seen.set(obj, true);

        // Handle Arrays
        if (Array.isArray(obj)) {
            return obj.map(item => clone(item));
        }

        // Handle Objects
        const output: any = {};
        for (const key in obj) {
            if (Object.prototype.hasOwnProperty.call(obj, key)) {
                // Skip 'ref' or other internal keys if necessary, but clone handles strict checks
                const val = clone(obj[key]);
                // Firestore doesn't like undefined, we converted it to null in base case if explicit
                // But if it's a property, let's keep it if it's not undefined
                if (val !== undefined) {
                    output[key] = val;
                }
            }
        }
        return output;
    };

    return clone(data);
};

// Safe Deep Clone replacement for JSON.parse(JSON.stringify())
const deepClone = <T>(obj: T): T => {
    return cleanData(obj) as T;
};

