            <input 
                type={type} 
                className={`w-full bg-[#0A1628] border border-gray-700 rounded-lg p-3 text-white focus:border-[#E67E50] outline-none transition-colors ${icon ? 'pl-10' : ''}`} 
                value={value} 
                onChange={e => onChange(e.target.value)} 
