const notifyMock = () => {
    const safeData = cleanData(mockTournaments);
    listeners.forEach(l => l(safeData));
    tournamentListeners.forEach(tl => {
        const t = safeData.find((tour: Tournament) => tour.id === tl.id);
        tl.cb(t ? t : null);
    });
};

